# Demo1: which comp touches another-color noise and bbox matches 5x4?
# Simpler unified hypothesis: for each candidate "object color", find cells of that color whose neighbors (8-dir) contain exactly one OTHER color; take union with that foreign cell; crop bbox; recolor foreign->object; check == output.
def test(inp,out):
    H,W=len(inp),len(inp[0])
    o=out
    res=[]
    for v in set(x for r in inp for x in r)-{0}:
        cells=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==v]
        groups={}
        import sys;sys.setrecursionlimit(10000)
        seen=set(); gidx=0
        for p in cells:
            if p in seen: continue
            st=[p]; group=[p]
            while st:
                a,b=st.pop()
                seen.add((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=a+da,b+db
                        if inp[x][y]==v and (x,y) not in seen: st.append((x,y))
            groups[gidx]=group; gidx+=1
        for k,group in groups.items():
            r0=min(r for r,_ in group); r1=max(r for r,_ in group)
            c0=min(c for _,c in group); c1=max(c for _,c in group)
            # noise cells adjacent (8-dir) to group
            noise=set()
            for r in range(max(0,r0-1),min(H-1,r1+1)+1):
                for c in range(max(0,c0-1),min(W-1,c1+1)+1):
                    if inp[r][c]!=v and (r,c) not in set(group):
                        noise.add((r,c))
            # keep only comps with exactly ONE noise cell inside? try all
            if len(noise)!=1: continue
            no=list(noise)[0]
            if abs(no[0]-r0)>1 or abs(no[1]-c1)<... : pass
            # bbox must include noise
            if not(min(r0,no[0])<=max(r1,no[0]) and min(c0,no[1])<=max(c1,no[1])): continue
            r0=min(r0,no[0]); r1=max(r1,no[0]); c0=min(c0,no[1]); c1=max(c1,no[1])
            box=[[inp[r][c_] for c_ in range(c0,c1+1)] for r in range(r0,r1+1)]
            b=[[v if x==v else 0 for x in row] for row in box]
            if b==out: res.append((v,tuple(sorted(group))+tuple(sorted(noise))))
    return res
