import sys; sys.setrecursionlimit(10000)
def f(inp,out):
    H,W=len(inp),len(inp[0])
    res=[]
    def g8(cells):
        seen=set(); groups=[]
        for p in cells:
            if p in seen: continue
            st=[p]; comp=[p]
            while st:
                a,b=st.pop()
                seen.add((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and inp[x][y]==inp[a][b] and (x,y) not in seen: st.append((x,y))
            groups.append(comp)
        return groups
    for v in set(x for r in inp for x in r)-{0}:
        groups=g8([(r,c) for r in range(H) for c in range(W) if inp[r][c]==v])
        for grp in groups:
            # count distinct colors in 8-neighborhood outside group
            nbcols=set()
            for r,c in grp:
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=r+da,c+db
                        if 0<=x<H and 0<=y<W and inp[x][y]!=v and (x,y) not in set(grp):
                            nbcols.add(inp[x][y])
            if len(nbcols)!=1: continue
            col=list(nbcols)[0]
            # union bbox + noise cell
            cells=set(grp)
            noise=[(r,c) for r in range(H) for c in range(W) if inp[r][c]==col and any(abs(r-a)<=1 and abs(c-b)<=1 for a,b in grp)]
            if len(noise)!=1: continue
            r0=min(min(r for r,_ in grp),noise[0][0]); r1=max(max(r for r,_ in grp),noise[0][0])
            c0=min(min(c for _,c in grp),noise[0][1]); c1=max(max(c for _,c in grp),noise[0][1])
            box=[[inp[r][c_] for c_ in range(c0,c1+1)] for r in range(r0,r1+1)]
            b=[[v if x==v else 0 for x in row] for row in box]
            if b==out: res.append((v,col,tuple(sorted(grp)),noise))
    return res
